cd /tmp_workspace && python3 - <<'EOF'
import json,re,csv
orals=json.load(open('orals.json'))
# fix html entities
import html as H
orals=[(i, H.unescape(t)) for i,t in orals]
json.dump(orals,open('orals.json','w'))
# load data.csv map
m={}
import csv
with open('iccv-2025-oral-papers/automation/data.csv') as f:
    for row in csv.DictReader(f):
        m[row['title'].strip().lower()]=row['paper'].strip()
def norm(s):
    return re.sub(r'[^a-z0-9]','',s.lower())
nmap={norm(k):v for k,v in m.items()}
out=[]
for i,t in orals:
    aid=nmap.get(norm(t),'')
    out.append({'id':i,'title':t,'arxiv_csv':aid})
json.dump(out,open('papers.json','w'),indent=1)
print("matched from csv:",sum(1 for x in out if x['arxiv_csv']),"/",len(out))
for x in out:
    if not x['arxiv_csv']:
        print("NO-CSV:",x['id'],x['title'][:70])
EOF
